mutation UpdateAlbum($id: ID!, $title: String, $userId: ID!) {
  updateAlbum(id: $id, input: {title: $title, userId: $userId}) {
    id
    title
    user {
      id
      name
    }
  }
}

mutation UpdateAlbum($id: ID!, $title: String, $userId: ID!, $sql: String!) {
  updateAlbum(id: $id, input: {title: $title, userId: $userId, sql: $sql}) {
    id
    title
    user {
      id
      name
    }
  }
}

